with target as (select * from regattas where slug in ('admirals-cup-2026-optimist','acdc-sailing-cup-2026-optimist','acdc-cup-international-sailing-championship-2026-optimist','thailand-international-sailing-championships-2026-optimist')), per_result as (select rr.id,rr.regatta_id,rr.rank,rr.entry_label,rr.total_score,rr.nett_score,count(race.id) as scores,sum(race.score) as gross,sum(race.score) filter(where not race.discarded) as net from regatta_results rr join target t on t.id=rr.regatta_id left join regatta_race_results race on race.regatta_result_id=rr.id group by rr.id) select jsonb_build_object('sheets',(select jsonb_agg(jsonb_build_object('slug',t.slug,'eventSlug',ev.slug,'status',t.status,'fleet',t.total_fleet_size,'raceCount',t.race_count,'source',t.official_results_url,'entries',(select count(*) from per_result p where p.regatta_id=t.id),'raceScores',(select sum(scores) from per_result p where p.regatta_id=t.id),'verifiedEntries',(select count(*) from regatta_results rr where rr.regatta_id=t.id and verification_status='verified'),'rankingCredit',t.counts_for_ranking) order by t.date) from target t join regatta_events ev on ev.id=t.event_id),'reconciliationExceptions',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from per_result p join target t on t.id=p.regatta_id where scores<>t.race_count or abs(p.total_score-p.gross)>.001 or abs(p.nett_score-p.net)>.001),'importedParentEvents',(select count(*) from admin_change_log where source='thai-optimist-2026-10-20' and action='results.import_official_thai2026'),'newProfileCount',(select count(*) from sailors where handle like '%-thai26-%')) as data;
